typeAlias.declarationTypeText:
Readonly<{
    /** 页面路由路径；必须以 / 开头，作为 URL 路由和注册表键。 */
    path: string;
    /** 页面标题；显示在导航树和浏览器标签页。 */
    title: string;
    /** 页面图标名；对应图标组件的标识，省略时导航树不显示图标。 */
    icon?: string;
    /** 页面描述；用于导航提示和 AI 理解页面功能。 */
    description?: string;
    /** 页面所属层级，决定它出现在哪一层菜单及以何种请求作用域执行。 */
    scope: PageScope;
    /** Vue 组件文件路径；必须位于 src/views/ 下且以 .vue 结尾，用于 Vite 动态 import。 */
    source: string;
    /** 不生成菜单项；仅作内嵌组件或借用宿主身份的伴随页。 */
    hidden?: boolean;
    /** 同层菜单中的分组标题；省略时直接位于该层顶级。 */
    group?: string;
    /** 同层菜单排序值，越小越靠前；分组按其成员最小值排序。 */
    order?: number;
    /** 页面消费的正式数据空间 ID，同时作为菜单项的蓝图场景身份。 */
    dataSpaceId?: string;
    /** 菜单项导航身份；省略时与 dataSpaceId 相同。 */
    navigationId?: string;
    /** 伴随页借用身份的宿主页面路径；伴随页本身必须 hidden。 */
    identityHost?: string;
}>

